\item[(a)] {\em Deterministic benchmark.}
There exists a \Algorithm $(\A,R_0)$ such that
\begin{align*}
\cost(\A|R_0)  &\leq \bench(i^*,\rho,T) + O(\Lambda \log T),
    \text{ where }
    \Lambda = \textstyle \sum_{i\neq i^*}
        \left(\bias_{i^*}-\bias_i \right)^{-2} ,\\
\error(\A|R_0) &\leq (k+1)\,\rho.
\end{align*}

\item[(b)] {\em Randomized benchmark.}
There exists a \Algorithm $(\A,R_0)$ such that
\begin{align*}
\cost(\A|R_0)
    &\leq O(\log T \log \tfrac{1}{\rho})
     \;(\bench(\mu^*,\rho,T))^{1+k/2} \\
   \error(\A|R_0) &\leq (k+1)\,\rho.
\end{align*}

