For any instance $\boldsymbol{\mathcal{D}} \in \mathcal{H}$ with variance vector $\boldsymbol{\sigma}^2$, any  UCB-procedure $\boldsymbol{{\sf UCB}}$, and any admissible width $\boldsymbol{{\sf w}}$, Algorithm \ref{algorithmucb} Variance-UCB($+\infty,T,\boldsymbol{{\sf UCB}}$) satisfies
    \begin{equation*}
        \textnormal{Regret}_{\infty,T}(\textnormal{V-UCB}, \boldsymbol{\mathcal{D}}|\mathcal{H}) \leq \mathbb{P}\left[\left(\boldsymbol{0} \leq \boldsymbol{{\sf UCB}} - \boldsymbol{\sigma} \leq \boldsymbol{\sigma}\boldsymbol{{\sf w}}\right)^{\sf c}\right] T + (1 + o(1))\left(\bar{w}_\infty(\boldsymbol{\sigma}, \boldsymbol{{\sf w}}) + \frac{G}{T}\right).
    \end{equation*}

For any instance $\boldsymbol{\mathcal{D}} \in \mathcal{H}^G$, any  UCB-procedure $\boldsymbol{{\sf UCB}}$, and any admissible width ${\sf w}$, the policy Variance-UCB instantiated at $\boldsymbol{{\sf UCB}}$ satisfies
    \begin{equation*}
        \textnormal{Regret}_{p,T}(\textnormal{V-UCB}, \boldsymbol{\mathcal{D}}|\mathcal{H}) \leq \mathbb{P}\left(\left(\boldsymbol{0} \leq \boldsymbol{{\sf UCB}} - \boldsymbol{\sigma} \leq \boldsymbol{\sigma}{\boldsymbol{\sf w}}\right)^{\sf c}\right)T + \frac{p+1}{2}(1 + o(1))\left(\bar{w}^2_p + \frac{G}{T}\right).
    \end{equation*}

\begin{equation*}
    \textnormal{Regret}_{\infty,T}(\textnormal{V-UCB}, \boldsymbol{\mathcal{D}}|\mathcal{H}) \leq 4\sqrt{3}(1+o(1))\frac{\|\hat{\boldsymbol{c}}\|_2}{\|\boldsymbol{\sigma}\|_2}\sqrt{\frac{G \log T}{T}},
\end{equation*}

and for any finite $p < +\infty$:
\begin{equation*}
    \textnormal{Regret}_{p,T}(\textnormal{V-UCB}, \boldsymbol{\mathcal{D}}|\mathcal{H}) \leq 85p(1 + o(1))\left(\sum_{g \in [G]} \frac{\hat{c}_g^2}{\sigma_g^2}\right)\frac{\log T}{T}.
\end{equation*}

