        \begin{equation*}
            \mathbb{E}_{\boldsymbol{\pi}}[R_p(\boldsymbol{n};\boldsymbol{\sigma})] - R^*_p(\boldsymbol{\sigma}) \leq \frac{4\sqrt{3}(1 + o(1))\|\boldsymbol{\sigma}\|_2\|\hat{\boldsymbol{c}}\|_2\sqrt{G}}{T^{3/2}}.
