(Almost sure sample complexity upper bound) For any problem instance $\boldsymbol{\mu}$, 
    \begin{enumerate}
        \item ATBOC-SubGauss satisfies
        \begin{equation}
        \mathbb{P}_{\boldsymbol{\mu}}\left[ \limsup_{\delta \rightarrow 0} \frac{\tau_\delta}{\log\left( 
        \frac{1}{\delta} \right)} \leq 2T_{mod}^*(\boldsymbol{\mu})\right] = 1.
    \end{equation}
    \item ATBOC-Gauss and ATBOC-1pExp satisfy
    \begin{equation}
        \mathbb{P}_{\boldsymbol{\mu}}\left[ \limsup_{\delta \rightarrow 0} \frac{\tau_\delta}{\log\left( 
        \frac{1}{\delta} \right)} \leq aT^*(\boldsymbol{\mu})\right] = 1,
    \end{equation}
    where
    \begin{equation}
        a = \begin{cases}
            2 &\text{ for ATBOC-Gauss} \\
            1+\zeta &\text{ for ATBOC-1pExp}
        \end{cases}, \text{ for } \zeta \in \left(0, \frac{1}{2}\right).
    \end{equation}
    \end{enumerate}

